UPDATE companies SET description='Namaste Solar, headquartered in Denver, Colorado, was founded in 2005 as a locally owned solar installation company. The business operates as an employee-owned cooperative and is a Certified B Corporation, reflecting a commitment to balancing profit with social and environmental responsibility. It began with a mission to propagate the responsible use of solar energy and pioneer conscientious business practices in the region.

The company designs, develops, builds, and maintains solar power systems for residential, commercial, public sector, non-profit, and community-scale projects. Its service portfolio includes battery backup, EV charger and heat pump installation, as well as ongoing maintenance. To date, Namaste Solar has completed more than 14,000 projects totaling over 215 megawatts of installed solar capacity, with operations managed from offices in Denver and Longmont.

Customers range from individual homeowners seeking to lock in electricity costs to businesses, municipalities, and non-profits pursuing sustainability goals. The firm has worked with commercial developers such as Westbrook Development Partners and serves public sector and non-profit clients through dedicated project teams. Its community solar initiatives provide subscription-based access to renewable energy for households unable to install rooftop systems.

Namaste Solar distinguishes itself through its cooperative ownership model, where all employee-owners participate in democratic, one-person-one-vote decision-making and open-book management. As a Certified B Corporation, it adheres to a Stakeholder Code of Conduct that balances the interests of customers, employees, community, and the environment. The company cites its 21-year track record and high customer satisfaction ratings as evidence of its people-first approach.', certifications=ARRAY['Certified B Corporation','CA License #1010955','RI License #42369']::text[], profile='{"capabilities": ["Solar system design and engineering", "Residential solar installation", "Commercial solar development and installation", "Battery backup installation", "EV charger installation", "Heat pump installation", "Service and ongoing maintenance", "Permitting and interconnection", "Project management", "Community solar development", "Public sector and non-profit solar projects", "Large-scale solar construction"], "industries": ["Residential", "Commercial", "Public Sector", "Non-Profit", "Community Solar", "Large-Scale Solar", "Renewable Energy"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Employee-owned cooperative with democratic one-person-one-vote governance", "Certified B Corporation meeting verified social and environmental standards", "Over 21 years of continuous operation in Colorado", "14,000+ solar projects installed totaling 215+ MW", "Highest Google review rating among local solar companies (600+ reviews)"], "facts_used": ["Founded in 2005 -> db", "Headquarters in Denver, Colorado -> db", "Employee-owned cooperative -> /about-us", "Certified B Corporation -> /about-us", "Over 21 years in business -> /", "14,000+ projects installed -> /", "215 MW of solar installed -> /", "Offices in Denver and Longmont -> /", "Services: residential, commercial, public sector, non-profit, community solar -> /about-us", "Mission: propagate responsible use of solar energy -> /about-us", "Democratic decision-making -> /about-us", "Open book management -> /about-us", "Stakeholder Code of Conduct -> /about-us", "Licenses: CA License #1010955, RI License #42369 -> /about-us", "LinkedIn URL -> db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Namaste Solar is a nationally recognized expert in developing, designing, building, and maintaining commercial solar projects.", "founded_year": "2005", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/namaste-solar/"], "ownership_tags": ["Employee-owned"]}'::jsonb, updated_at=now() WHERE slug='namaste-solar' AND approved AND profile IS NULL;
