UPDATE companies SET description='Nashville Wood operates from Nashville, Tennessee. The family-owned sawmill was first established in 2006 and re-established in 2023. The founders are not named, but the business began with a mission to rescue landfill-bound timber and give it a second life.

The company produces artistic lumber with a focus on walnut, all sourced locally from the Nashville area. Its process includes slabbing logs, air-drying the wood in flitches (keeping each log''s boards together) rather than kiln-drying, and cutting every piece live edge so customers can decide final dimensions. The shop also offers custom milling and planing services. As a small family operation, it does not disclose facility size or headcount.

The flitch-drying method allows clients to build entire pieces from matching lumber. The company also seeks partnerships with charitable organizations in need of lumber.

Nashville Wood differentiates itself by avoiding kiln drying to preserve natural wood colors, by keeping flitches intact for grain matching, and by selling exclusively live-edge slabs that let the end user control the final cut. The business was founded on the principle of diverting usable timber from landfills.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Sawmilling", "Slabbing", "Air drying", "Flitch drying", "Live edge cutting", "Custom milling", "Planing", "Lumber sales"], "industries": ["Woodworking", "Furniture making", "Artistic woodworking"], "materials": ["Walnut", "Local hardwoods", "Reclaimed timber"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Air-dried lumber (no kiln) to preserve natural color", "Flitch drying keeps boards from the same log together for consistent grain", "Live-edge slabs let customers determine final trim", "100% locally sourced from the Nashville region", "Custom milling and planing available"], "facts_used": ["Founded 2006 and re-established 2023 -> /about", "Family owned and operated -> /about", "Located in Nashville, TN -> /about, db", "Specializes in artistic lumber with focus on walnut -> /about, /", "100% locally sourced from Nashville area -> /about", "Slabbed and fully air dried to preserve color -> /about", "Dry wood in flitches (by log) -> /about", "Cut everything live edge -> /about", "Custom milling and planing services -> /", "Mission: give landfill-bound timber a second life -> /", "Seeks charitable organization partnerships -> /about", "Social media: Instagram, YouTube -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are a small, family owned and operated sawmill established in 2006 and again in 2023.", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='nashville-wood-by-appointment-only' AND approved AND profile IS NULL;
