UPDATE companies SET description='Nebraska Scooter Mart LLC opened in January 2004 in Lincoln, Nebraska, as a locally owned medical equipment store. Since its founding, the business has served the Lincoln area as a dedicated provider of mobility assistive equipment, building a reputation for consistent local presence.

The company operates as a medical equipment retailer, offering a selection that includes hospital beds and related products, as well as bath safety products and other mobility assistive devices. In addition to sales, the firm maintains a staff of service technicians who perform equipment repair and maintenance, supporting the products they sell through both in-shop and on-site service.

Nebraska Scooter Mart distinguishes itself as the longest-tenured locally owned medical equipment store in Lincoln. The company also points to its team of dedicated professionals, who collectively hold an average of 20 years of experience in the field of mobility assistive equipment, as a key reason customers rely on their expertise for both product selection and ongoing support.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Medical equipment sales", "Equipment repair and maintenance", "Technical support and service"], "industries": ["Mobility assistive equipment", "Medical equipment"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Longest-tenured locally owned medical equipment store in Lincoln", "Team with average 20 years of experience in mobility assistive equipment", "In-house service technicians for equipment repair and maintenance", "Focus on hospital beds and bath safety products"], "facts_used": ["Founded January 2004 -> db", "Located in Lincoln, Nebraska -> db", "Locally owned -> db", "Medical equipment store -> db", "Offers hospital beds and bath safety products -> db", "Provides service technicians -> db", "Team average 20 years experience -> db", "Longest tenured locally owned medical equipment store in Lincoln -> db"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Nebraska Scooter Mart opened in January 2004 and is now the longest tenured locally owned medical equipment store in Lincoln.", "founded_year": "2004", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='nebraska-scooter-mart-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Nemo Manufacturing Inc is an electronic contract manufacturer based in La Grange, Missouri. The company specializes in surface-mount (SMT) and through-hole (PTH) printed circuit board assemblies, offering services from prototype through production volumes.

