UPDATE companies SET description='Nicolet Plastics operates from two Wisconsin facilities: a 41,000-square-foot plant in Mountain and a 31,000-square-foot plant in Jackson.

The molder runs 46 injection molding presses ranging from 30 to 610 tons across both sites, supported by advanced temperature controllers and real-time monitoring software. Core capabilities include custom plastic injection molding, specialized automated insert molding cells, tight-tolerance and micro molding, and additive manufacturing via Carbon 3D plastic printing and Mantle 3D metal printing. Post-molding services encompass CNC machining, ultrasonic and vibration welding, pad printing, over molding, heat staking, and both manual and automated assembly. The in-house tool room maintains customer molds and assists with design improvements, while engineering support covers design for manufacturability, prototype development, and metal-to-plastic conversion.

Nicolet serves equipment manufacturers in industrial, medical, marine, aerospace, consumer products, commercial goods, and sporting goods sectors. Its customer base includes well-known companies requiring complex parts molded from commodity and engineered resins.

The company highlights its cross-trained workforce and customer education program—recognized by Plastics News as a Best Place to Work for 2026 and a 2016 Insight Innovation Award winner for training. The tool-making heritage remains a differentiator, enabling mold maintenance and part-design optimization that reduce lead times and cost.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Plastic injection molding", "Insert molding", "Micro molding", "Tight tolerance molding", "Additive manufacturing (Carbon 3D printing)", "Additive manufacturing (Mantle metal printing)", "CNC machining", "Ultrasonic welding", "Vibration welding", "Pad printing", "Over molding", "Heat staking", "Assembly", "Sub-assembly", "Tooling support", "Prototype support", "Design for manufacturability", "Metal-to-plastic conversion", "Post-molding operations", "Hot plate welding", "Rapid tooling", "Engineering & product support", "Value-added operations"], "industries": ["Industrial", "Medical", "Marine", "Aerospace", "Consumer products", "Commercial goods", "Sporting goods"], "materials": ["Commodity resins", "Engineering resins", "Over 200 material options", "Engineering-grade materials (additive)", "Steel (mold bases)"], "equipment": ["46 injection molding presses (30-610 tons)", "Carbon 3D printer", "Mantle 3D metal printer", "Advanced temperature controllers", "Real-time monitoring software"], "volume": "Low to high volume", "lead_time": "", "tolerances": "", "built_on": ["46 injection molding presses (30\u2013610 tons) across two Wisconsin facilities", "In-house tool-making shop for mold maintenance and part-design improvement", "Carbon 3D plastic printing and Mantle 3D metal printing for rapid prototyping and production", "Specialized automated insert molding cells for dedicated production", "Free customer training through Nicolet Plastics University"], "facts_used": ["Founded in 1986 -> /about", "Two facilities in Mountain and Jackson, Wisconsin -> /about", "41,000 sq ft Mountain facility, 31,000 sq ft Jackson facility -> /about", "46 injection molding presses 30-610 tons -> /about", "Industries served: industrial, medical, marine, aerospace, consumer products, commercial goods, sporting goods -> /about, /", "Capabilities: injection molding, insert molding, micro molding, additive manufacturing (Carbon, Mantle), CNC machining, welding, assembly, etc. -> /, /services", "Materials: over 200 commodities and engineering resins -> /services", "Plastics News Best Places to Work 2026 -> /about", "2016 Insight Innovation Award for employee training -> /about", "Tool-making shop maintains molds and improves part design -> /about", "Nicolet Plastics University free training -> /services", "Metal-to-plastic conversion -> /services", "Design for manufacturability -> /services", "Rapid tooling -> /services", "Headquarters: Mountain, Wisconsin -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Nicolet Plastics specializes in low-to-high-volume plastic injection molding", "founded_year": "1986", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='nicolet-plastics-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='The company produces custom Molesworth-style furniture and luxury ranch pieces, a specialization it has held for the past 27 years. Each item is built in their Cody showroom and workshop using walnut, juniper, and distinctive burl wood for legs and drawer pulls. Details include leather upholstery, hand-painted panels, rawhide-sculpted accents, Chimayo woven textiles, and half-round pole construction. They accept designs ranging from formal drawings to napkin sketches.

The firm''s work has been featured in Mountain Living, Cowgirl Magazine, Log Home Living, Big Sky Journal, and Cowboys & Indians.

Gallis describes their philosophy simply: "We build furniture as if it were for ourselves. If it''s not good enough for our house, it''s not good enough for the client." That standard, combined with the ability to translate rough ideas into finished pieces, has sustained the shop for over five decades.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Molesworth style reproduction", "Woodworking (walnut, juniper)", "Burl wood detailing", "Leather upholstery", "Hand painted panels", "Rawhide sculpted panels", "Chimayo weaving textiles", "Half round pole construction", "Custom rustic western furniture"], "industries": ["Luxury residential furniture", "Western ranch furniture", "Interior design", "High-end custom woodworking"], "materials": ["Walnut", "Juniper", "Burl wood", "Leather", "Rawhide", "Chimayo textiles", "Paint", "Half round poles (wood)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Build furniture to personal-household standard", "Accept designs from napkin sketches", "27+ years specializing in Molesworth style", "Incorporate walnut and juniper accents", "Featured in national western luxury publications"], "facts_used": ["Founded 1971 -> db", "Headquarters Cody, Wyoming -> db", "Owner John Gallis -> / and /about", "Ian Gallis employed 17 years, worked with father 24 years -> /about", "John Gallis was Bloomingdale''s chief high-end cabinetmaker 14 years -> /about", "Specializes in Molesworth style for 27 years -> /about", "Makes custom Molesworth style and luxury ranch furniture -> /", "Materials: walnut, juniper, burl wood, leather, rawhide, Chimayo weavings, hand painted panels, half round poles -> /", "Works from sketches/napkin drawings -> / and /about", "Showroom and shop in Cody -> /", "Featured in Mountain Living, Cowgirl Magazine, Log Home Living, Big Sky Journal, Cowboys & Indians -> /", "Quote: build furniture as if for ourselves -> /"], "company_type": "Manufacturer", "ma