UPDATE companies SET description='Northeast Solar is a residential energy services company based in Hatfield, Massachusetts, founded in 2015. The company serves homeowners across four counties in Western Massachusetts, offering integrated energy systems that combine solar generation, battery storage, heat-pump mini-splits, and electric-vehicle charging.

The firm designs and installs complete home energy systems rather than selling standalone equipment. All installation work is performed by Northeast Solar''s own licensed employees; the company does not use subcontractors. Since inception it has completed more than 2,000 installations.

The customer base consists exclusively of residential property owners in Western Massachusetts seeking to replace variable utility bills with fixed-cost energy, improve resilience during grid outages, and reduce heating and cooling expenses. Typical projects include solar leases with zero down payment and a 25-year fixed rate, mini-split retrofits that qualify for Mass Save rebates up to $8,500, and battery systems that provide backup power.

Northeast Solar differentiates itself by maintaining a single, directly employed crew across all trades, a 10-year workmanship warranty, and certifications including A+ Better Business Bureau rating (since 2015), Enphase Gold Installer status, Mitsubishi Diamond Installer status, and Mass Save Certified Heat Pump Installer designation. The company emphasizes long-term local support over rapid growth.', certifications=ARRAY['Enphase Gold Installer','Mitsubishi Diamond Installer','Mass Save Certified Heat Pump Installer']::text[], profile='{"capabilities": ["Solar PV system design and installation", "Battery energy storage system installation", "Mini-split heat pump installation", "EV charging station installation", "Home energy assessment (Power Plan)", "Solar lease and financing arrangement", "Mass Save rebate application assistance", "0% Heat Loan facilitation"], "industries": ["Residential solar installation", "Residential energy storage", "Residential HVAC (heat pumps)", "EV charging infrastructure", "Home energy management"], "materials": [], "equipment": ["Enphase microinverter systems", "Mitsubishi Electric mini-split systems"], "volume": "2,000+ residential installations since 2015", "lead_time": "", "tolerances": "", "built_on": ["All installation performed by direct employees; no subcontracting", "Enphase Gold Installer and Mitsubishi Diamond Installer certifications", "Mass Save Certified Heat Pump Installer", "Integrated ''full energy stack'' \u2014 solar, storage, mini-splits, EV charging \u2014 under one roof"], "facts_used": ["Founded 2015 -> db", "Headquarters Hatfield, MA -> db", "2,000+ installations -> page /", "15 years in business -> page /", "No subcontracting, all employees -> page /", "A+ BBB rated since 2015 -> page /", "Enphase Gold Installer -> page /", "Mitsubishi Diamond Installer -> page /", "Mass Save Certified Heat Pump Installer -> page /", "Full energy stack (solar, storage, mini-splits, EV charging) -> page /", "Solar leasing $0 down fixed 25 years -> page /", "Mini-split rebates up to $8,500 -> page /", "Serves Western Massachusetts (four counties) -> page /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Northeast Solar designs complete home energy systems for Western Massachusetts homeowners", "founded_year": "2015", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='northeast-solar' AND approved AND profile IS NULL;
